<h1>Approval workflow inbox</h1><p>Pending approval instances and historical decisions.</p><?php if($m=flash('success')):?><div class="alert success"><?=e($m)?></div><?php endif?><?php if($m=flash('error')):?><div class="alert error"><?=e($m)?></div><?php endif?><div class="panel table-wrap"><table><tr><th>ID</th><th>Workflow</th><th>Document</th><th>Current step</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $row):?><tr><td><?=e($row['id'])?></td><td><?=e($row['workflow_name'])?></td><td><?=e($row['document_type'].' #'.$row['document_id'])?></td><td><?=e($row['current_step_order'])?></td><td><?=e($row['status'])?></td><td><?php if($row['status']==='pending'):?><form method="post" action="<?=e(url('/approvals/act'))?>"><?=csrf_field()?><input type="hidden" name="instance_id" value="<?=e($row['id'])?>"><select name="decision"><option value="approved">Approve</option><option value="rejected">Reject</option><option value="returned">Return</option></select><input name="comments" placeholder="Comments"><button class="btn">Submit</button></form><?php endif?></td></tr><?php endforeach?></table></div>
